                                    llmReport.append("Test Type: ✅ POSITIVE\n");
                                    llmReport.append("Analysis Result: ").append(validationResult.isFailed() ? "❌ SOFT ERROR DETECTED" : "✅ VALID SUCCESS").append("\n\n");
